type GongstructMarshallable interface {
	GongstructPtr
	GongMarshallIdentifier(stage *Stage) string
	GongMarshallAllFields(stage *Stage) (string, string)
}

func gongMarshallInstances[T GongstructMarshallable](
	stage *Stage,
	instances map[T]struct{},
	identifiersDecl *strings.Builder,
	initializerStatements *strings.Builder,
	pointersInitializesStatements *strings.Builder,
) {
	if len(instances) == 0 {
		return
	}
	ordered := make([]T, 0, len(instances))
	for instance := range instances {
		ordered = append(ordered, instance)
	}
	sort.Slice(ordered, func(i, j int) bool {
		return ordered[i].GongGetOrder(stage) < ordered[j].GongGetOrder(stage)
	})
	identifiersDecl.WriteString("\n")
	for _, instance := range ordered {
		identifiersDecl.WriteString(instance.GongMarshallIdentifier(stage))
		initRes, ptrRes := instance.GongMarshallAllFields(stage)
		initializerStatements.WriteString("\n" + initRes)
		pointersInitializesStatements.WriteString(ptrRes)
	}
}


// MarshallFile marshall the stage content into a file as an instanciation into a stage
// according to the marshalling policy of the stage.
//
// In GongMarshallingAppendCommit mode, it will append the last commit to the file.
// In other modes, it will rewrite the entire file.
func (stage *Stage) MarshallFile(filename, modelsPackageName, packageName string) {

	if stage.GetGongMarshallingMode() == GongMarshallingAppendCommit {
		contentBytes, err := os.ReadFile(filename)

		// if the file does not exist, marshall the full stage
		if os.IsNotExist(err) {
			file, createErr := os.Create(filename)
			if createErr != nil {
				log.Fatal(createErr.Error())
			}
			defer file.Close()
			stage.Marshall(file, modelsPackageName, packageName)
			return
		}
		if err != nil {
			log.Fatal(err.Error())
		}

		content := string(contentBytes)

		if stage.IsSquashing() {
			// we squash: we want to clear the current function body
			// and let the append logic write the squashed commit
			const fnSig = "func _(stage *barline.Stage) {"
			if before, _, ok := strings.Cut(content, fnSig); ok {
				content = before + fnSig + "\n}\n"
			}
		}

		if stage.IsApplyingBackwardCommit() {
			// we are going backward, we need to remove the last forward commit from the file

			// because commitsBehind has been incremented before the call to this function
			// the index of the commit to remove is len(forwardCommits) - commitsBehind
			forwardCommits := stage.GetForwardCommits()
			commitIndexToRemove := len(forwardCommits) - stage.GetCommitsBehind()

			if commitIndexToRemove < 0 || commitIndexToRemove >= len(forwardCommits) {
				return // Should not happen if history is consistent
			}

			commitToRemove := forwardCommits[commitIndexToRemove]

			lastIndex := strings.LastIndex(content, commitToRemove+"\n")
			if lastIndex != -1 {
				newContent := content[:lastIndex] + content[lastIndex+len(commitToRemove)+1:]
				err = os.WriteFile(filename, []byte(newContent), 0644)
				if err != nil {
					log.Fatal(err.Error())
				}
			} else {
				lastIndex = strings.LastIndex(content, commitToRemove)
				if lastIndex != -1 {
					newContent := content[:lastIndex] + content[lastIndex+len(commitToRemove):]
					err = os.WriteFile(filename, []byte(newContent), 0644)
					if err != nil {
						log.Fatal(err.Error())
					}
				} else {
					// The commit block was not found. This typically happens for the initial
					// commit which is formatted differently (the lines after func _(stage *models.Stage) {).
					// We rewrite the entire file with the current (rewound) stage state to safely remove it.
					file, createErr := os.Create(filename)
					if createErr != nil {
						log.Fatal(createErr.Error())
					}
					defer file.Close()
					stage.Marshall(file, modelsPackageName, packageName)
				}
			}
			return // we are done for the backward case
		}

		if stage.IsApplyingForwardCommit() {
			// bypass the modified check
		} else if !stage.IsModified() {
			return
		}

		forwardCommits := stage.GetForwardCommits()
		if len(forwardCommits) == 0 {
			return // nothing to do
		}

		activeCommits := len(forwardCommits) - stage.GetCommitsBehind()
		if activeCommits <= 0 {
			return
		}
		forwardCommit := forwardCommits[activeCommits-1]

		// append before the ending brace of the func
		lastBrace := strings.LastIndex(content, "}")
		if lastBrace == -1 {
			// if no brace, something is wrong with the file, so we rewrite it
			file, createErr := os.Create(filename)
			if createErr != nil {
				log.Fatal(createErr.Error())
			}
			defer file.Close()
			stage.Marshall(file, modelsPackageName, packageName)
			return
		}

		contentBeforeBrace := content[:lastBrace]
		trimmedContentBeforeBrace := strings.TrimSpace(contentBeforeBrace)
		emptyBody := stage.IsSquashing() ||
			strings.HasSuffix(trimmedContentBeforeBrace, "func _(stage *barline.Stage) {") ||
			strings.HasSuffix(trimmedContentBeforeBrace, "// insertion point for setup of pointers")

		// check if the file ends with stage.Commit() before the brace
		if !emptyBody && !strings.HasSuffix(trimmedContentBeforeBrace, "stage.Commit()") {
			contentBeforeBrace = contentBeforeBrace + "\n\tstage.Commit()\n"
		}

		// insert the commit statements before the last brace
		newContent := contentBeforeBrace + forwardCommit + "\n" + content[lastBrace:]

		err = os.WriteFile(filename, []byte(newContent), 0644)
		if err != nil {
			log.Fatal(err.Error())
		}

	} else {
		file, err := os.Create(filename)
		if err != nil {
			log.Fatal(err.Error())
		}
		defer file.Close()

		stage.Marshall(file, modelsPackageName, packageName)
	}
}

// Marshall marshall the stage content into the file as an instanciation into a stage
func (stage *Stage) Marshall(file *os.File, modelsPackageName, packageName string) {

	name := file.Name()

	if !strings.HasSuffix(name, ".go") {
		log.Println(name + " is not a go filename")
	}

	log.Printf("Marshalling %s", name)

	res, err := stage.MarshallToString(modelsPackageName, packageName)
	if err != nil {
		log.Fatalln("Error marshalling to string:", err)
	}

	fmt.Fprintln(file, res)
}

// MarshallToString marshall the stage content into a string
func (stage *Stage) MarshallToString(modelsPackageName, packageName string) (res string, err error) {

	res = marshallRes
	res = strings.ReplaceAll(res, "{{PackageName}}", packageName)
	res = strings.ReplaceAll(res, "{{ModelsPackageName}}", modelsPackageName)

	probePackageName := modelsPackageName + "/probe/cmd/probe"
	res = strings.ReplaceAll(res, "{{ProbePackageName}}", probePackageName)

	var goModuleVersion string
	if buildInfo, ok := debug.ReadBuildInfo(); ok {
		goModuleVersion = buildInfo.Main.Version
	}
	res = strings.ReplaceAll(res, "{{GoModuleVersion}}", goModuleVersion)
	
	goModuleVersionWithoutDirty := strings.ReplaceAll(goModuleVersion, "+dirty", "")
	if goModuleVersionWithoutDirty == "" || goModuleVersionWithoutDirty == "(devel)" {
		goModuleVersionWithoutDirty = "latest"
	}
	res = strings.ReplaceAll(res, "{{GoModuleVersionWithoutDirty}}", goModuleVersionWithoutDirty)

	// map of identifiers
	var identifiersDecl strings.Builder
	var initializerStatements strings.Builder
	var pointersInitializesStatements strings.Builder

	// insertion initialization of objects to stage
	gongMarshallInstances(stage, stage.BarStyleColors, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	gongMarshallInstances(stage, stage.Barlines, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	gongMarshallInstances(stage, stage.Endings, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	gongMarshallInstances(stage, stage.Repeats, &identifiersDecl, &initializerStatements, &pointersInitializesStatements)
	res = strings.ReplaceAll(res, "{{Identifiers}}", identifiersDecl.String())
	res = strings.ReplaceAll(res, "{{ValueInitializers}}", initializerStatements.String())
	res = strings.ReplaceAll(res, "{{PointersInitializers}}", pointersInitializesStatements.String())

	if len(stage.MetaPackageImports) > 0 {
		var importDecls strings.Builder
		for _, imp := range stage.MetaPackageImports {
			importDecls.WriteString(fmt.Sprintf("\n\t%s %s", imp.Alias, imp.Path))
		}
		res = strings.ReplaceAll(res, "{{ImportPackageDeclaration}}", importDecls.String())

		var dummyDecls strings.Builder
		for _, imp := range stage.MetaPackageImports {
			dummyDecls.WriteString(fmt.Sprintf("\nvar _ %s.Stage", imp.Alias))
		}
		res = strings.ReplaceAll(res, "{{ImportPackageDummyDeclaration}}", dummyDecls.String())
	} else if stage.MetaPackageImportAlias != "" {
		res = strings.ReplaceAll(res, "{{ImportPackageDeclaration}}",
			fmt.Sprintf("\n\t%s %s", stage.MetaPackageImportAlias, stage.MetaPackageImportPath))

		res = strings.ReplaceAll(res, "{{ImportPackageDummyDeclaration}}",
			fmt.Sprintf("\nvar _ %s.Stage",
				stage.MetaPackageImportAlias))

		var entries strings.Builder

		// regenerate the map of doc link renaming
		// the key and value are set to the value because
		// if it has been renamed, this is the new value that matters
		valuesOrdered := make([]GONG__Identifier, 0)
		for _, value := range stage.Map_DocLink_Renaming {
			valuesOrdered = append(valuesOrdered, value)
		}
		sort.Slice(valuesOrdered[:], func(i, j int) bool {
			return valuesOrdered[i].Ident < valuesOrdered[j].Ident
		})
		for _, value := range valuesOrdered {

			// get the number of points in the value to find if it is a field
			// or a struct

			switch value.Type {
			case GONG__ENUM_CAST_INT:
				entries.WriteString(fmt.Sprintf("\n\n\t\"%s\": %s(0),", value.Ident, value.Ident))
			case GONG__ENUM_CAST_STRING:
				entries.WriteString(fmt.Sprintf("\n\n\t\"%s\": %s(\"\"),", value.Ident, value.Ident))
			case GONG__FIELD_VALUE:
				// substitute the second point with "{})."
				joker := "__substitute_for_first_point__"
				valueIdentifier := strings.Replace(value.Ident, ".", joker, 1)
				valueIdentifier = strings.Replace(valueIdentifier, ".", "{}).", 1)
				valueIdentifier = strings.Replace(valueIdentifier, joker, ".", 1)
				entries.WriteString(fmt.Sprintf("\n\n\t\"%s\": (%s,", value.Ident, valueIdentifier))
			case GONG__IDENTIFIER_CONST:
				entries.WriteString(fmt.Sprintf("\n\n\t\"%s\": %s,", value.Ident, value.Ident))
			case GONG__STRUCT_INSTANCE:
				entries.WriteString(fmt.Sprintf("\n\n\t\"%s\": &(%s{}),", value.Ident, value.Ident))
			}
		}

		// res = strings.ReplaceAll(res, "{{EntriesDocLinkStringDocLinkIdentifier}}", entries.String())
	} else {
		res = strings.ReplaceAll(res, "{{ImportPackageDeclaration}}", "")
		res = strings.ReplaceAll(res, "{{ImportPackageDummyDeclaration}}", "")
	}
	return
}

// insertion point for marshall field methods
func (barstylecolor *BarStyleColor) GongMarshallField(stage *Stage, fieldName string) (res string) {
	ident := barstylecolor.GongGetIdentifier(stage)
	_ = ident
	switch fieldName {
	case "Name":
		res = __gong__marshallString(ident, "Name", barstylecolor.Name)
	case "Color":
		res = __gong__marshallString(ident, "Color", barstylecolor.Color)
	case "Value":
		res = __gong__marshallEnumString(ident, "Value", barstylecolor.Value.ToCodeString())

	default:
		log.Panicf("Unknown field %s for Gongstruct BarStyleColor", fieldName)
	}
	return
}

func (barline *Barline) GongMarshallField(stage *Stage, fieldName string) (res string) {
	ident := barline.GongGetIdentifier(stage)
	_ = ident
	switch fieldName {
	case "Name":
		res = __gong__marshallString(ident, "Name", barline.Name)
	case "Location":
		res = __gong__marshallEnumString(ident, "Location", barline.Location.ToCodeString())
	case "Segno":
		res = __gong__marshallString(ident, "Segno", barline.Segno)
	case "Coda":
		res = __gong__marshallString(ident, "Coda", barline.Coda)
	case "Divisions":
		res = __gong__marshallString(ident, "Divisions", barline.Divisions)
	case "Id":
		res = __gong__marshallString(ident, "Id", barline.Id)

	case "BarStyle":
		if barline.BarStyle != nil {
			res = __gong__marshallPointer(ident, "BarStyle", barline.BarStyle.GongGetIdentifier(stage))
		} else {
			res = __gong__marshallPointer(ident, "BarStyle", "nil")
		}
	case "Ending":
		if barline.Ending != nil {
			res = __gong__marshallPointer(ident, "Ending", barline.Ending.GongGetIdentifier(stage))
		} else {
			res = __gong__marshallPointer(ident, "Ending", "nil")
		}
	case "Repeat":
		if barline.Repeat != nil {
			res = __gong__marshallPointer(ident, "Repeat", barline.Repeat.GongGetIdentifier(stage))
		} else {
			res = __gong__marshallPointer(ident, "Repeat", "nil")
		}
	default:
		log.Panicf("Unknown field %s for Gongstruct Barline", fieldName)
	}
	return
}

